"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[39706],{4314:e=>{e.exports=JSON.parse('{"label":"api","permalink":"/CARTESI-docs2/pr-preview/pr-8/tags/api","allTagsPath":"/CARTESI-docs2/pr-preview/pr-8/tags","count":5,"items":[{"id":"compute/logger_drive","title":"Logger drives","description":"A relevant limitation of the Cartesi Machines as they have been described until now is the size of their input drives.","permalink":"/CARTESI-docs2/pr-preview/pr-8/compute/logger_drive"},{"id":"compute/machine-offchain","title":"Machines off-chain","description":"Although an extensive documentation of Cartesi Machines can be found here, one may choose to skip this reading and jump right away to their usage inside the blockchain through Cartesi Compute. For that, it is enough to regard a Cartesi Machine as a black box that executes computations.","permalink":"/CARTESI-docs2/pr-preview/pr-8/compute/machine-offchain"},{"id":"compute/machine-onchain","title":"Machines on-chain","description":"Having discussed the concept of Cartesi Machines off-chain, capable of booting a Linux operating system and loading heavy-weight libraries, one naturally wonders how this will ever be stored or executed on the limited environment of a blockchain. The simple answer is that it won\u2019t be.","permalink":"/CARTESI-docs2/pr-preview/pr-8/compute/machine-onchain"},{"id":"compute/api","title":"On-chain API","description":"Having informally discussed how Cartesi Compute represents Cartesi Machines on-chain, one can now describe in more details the API for requesting and retrieving computations in Cartesi Compute.","permalink":"/CARTESI-docs2/pr-preview/pr-8/compute/api"},{"id":"compute/off-chain-api","title":"The off-chain API","description":"After the call for instantiate, the blockchain may already have all information that is necessary to execute the machine. But in many cases it also needs to get input from other users. In a game for example, the user may need to insert their decisions on input drives for later processing.","permalink":"/CARTESI-docs2/pr-preview/pr-8/compute/off-chain-api"}]}')}}]);